#!/usr/bin/env python3
"""Assemble pinned WASI fixtures and materialize their D test module."""
import argparse
import hashlib
from pathlib import Path
import shutil
import subprocess
import tempfile


REVISION = "32656dc4873fcec5c8662aa937bd01acda3b2e85"


def main():
    cli = argparse.ArgumentParser(description=__doc__)
    cli.add_argument("--wasmtime-source", required=True, type=Path)
    cli.add_argument("--assembler", required=True, type=Path)
    cli.add_argument("--wasm-dir", required=True, type=Path)
    cli.add_argument("--d-output", required=True, type=Path)
    args = cli.parse_args()
    fixtures = Path(__file__).resolve().parent
    head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=args.wasmtime_source, text=True).strip()
    if head != REVISION:
        raise SystemExit("WIT fixtures require the pinned Wasmtime revision")
    args.wasm_dir.mkdir(parents=True, exist_ok=True)
    results = []
    with tempfile.TemporaryDirectory(prefix="flint-wasi-wit-") as directory:
        for name in ("core", "unexpected", "preview1", "wasi02", "wasi03"):
            output = args.wasm_dir / f"{name}.wasm"
            command = [args.assembler.resolve(), fixtures / f"{name}.wat", output]
            if name in ("wasi02", "wasi03"):
                version = "p2" if name == "wasi02" else "p3"
                wit = Path(directory) / name
                shutil.copytree(fixtures / name / "wit", wit)
                trusted = args.wasmtime_source / f"crates/wasi/src/{version}/wit/deps"
                shutil.copytree(trusted, wit / "deps", dirs_exist_ok=True)
                command[1] = fixtures / name / "plugin.wat"
                command.append(wit)
            subprocess.run(command, check=True)
            raw = output.read_bytes()
            results.append((name, raw))
            print(f"{hashlib.sha256(raw).hexdigest()}  {output}")
    source = ["// Generated by tests/fixtures/generate.py.", "module flint.engine.wasi.fixture_bytes;", "", "@safe:", ""]
    for name, raw in results:
        source += [f'/// Materialized {name} test guest.', f'immutable ubyte[] {name} = cast(immutable(ubyte)[]) x"']
        source += ["    " + raw[i:i + 24].hex(" ") for i in range(0, len(raw), 24)]
        source += ['";', ""]
    args.d_output.write_text("\n".join(source))


if __name__ == "__main__":
    main()
